"use client";

import * as React from "react";
import { ThemeProvider as NextThemesProvider, useTheme } from "next-themes";

export type HaloTheme = "light" | "dark" | "system";
export type HaloMaterialIntensity = "subtle" | "balanced" | "rich";

export interface HaloThemeContextValue {
  theme: HaloTheme;
  setTheme: (theme: HaloTheme) => void;
  resolvedTheme: "light" | "dark";
  materialIntensity: HaloMaterialIntensity;
  setMaterialIntensity: (intensity: HaloMaterialIntensity) => void;
}

const HaloThemeContext = React.createContext<HaloThemeContextValue | undefined>(undefined);

export interface HaloThemeProviderProps {
  children: React.ReactNode;
  defaultTheme?: HaloTheme;
  defaultMaterialIntensity?: HaloMaterialIntensity;
  storageKey?: string;
  intensityStorageKey?: string;
  attribute?: React.ComponentProps<typeof NextThemesProvider>["attribute"];
  enableSystem?: boolean;
  disableTransitionOnChange?: boolean;
}

function HaloThemeInnerProvider({
  children,
  defaultMaterialIntensity = "balanced",
  intensityStorageKey = "halo-material-intensity",
}: {
  children: React.ReactNode;
  defaultMaterialIntensity?: HaloMaterialIntensity;
  intensityStorageKey?: string;
}) {
  const nextThemes = useTheme();
  const [materialIntensity, setMaterialIntensityState] =
    React.useState<HaloMaterialIntensity>(defaultMaterialIntensity);
  const [mounted, setMounted] = React.useState(false);

  // Sync intensity with localStorage
  React.useEffect(() => {
    setMounted(true);
    try {
      const stored = localStorage.getItem(intensityStorageKey);
      if (stored === "subtle" || stored === "balanced" || stored === "rich") {
        setMaterialIntensityState(stored);
      }
    } catch {
      // Ignore localStorage errors (e.g. iframe / disabled cookies)
    }
  }, [intensityStorageKey]);

  const setMaterialIntensity = React.useCallback(
    (intensity: HaloMaterialIntensity) => {
      setMaterialIntensityState(intensity);
      try {
        localStorage.setItem(intensityStorageKey, intensity);
      } catch {
        // Ignore localStorage errors
      }
      if (typeof document !== "undefined") {
        document.documentElement.setAttribute("data-material-intensity", intensity);
      }
    },
    [intensityStorageKey]
  );

  React.useEffect(() => {
    if (mounted && typeof document !== "undefined") {
      document.documentElement.setAttribute("data-material-intensity", materialIntensity);
    }
  }, [materialIntensity, mounted]);

  const value = React.useMemo<HaloThemeContextValue>(() => {
    const rawTheme = (nextThemes.theme as HaloTheme) || "system";
    const resolved = (nextThemes.resolvedTheme as "light" | "dark") || "dark";
    return {
      theme: rawTheme,
      setTheme: (t: HaloTheme) => nextThemes.setTheme(t),
      resolvedTheme: resolved,
      materialIntensity,
      setMaterialIntensity,
    };
  }, [nextThemes.theme, nextThemes.resolvedTheme, nextThemes.setTheme, materialIntensity, setMaterialIntensity]);

  return <HaloThemeContext.Provider value={value}>{children}</HaloThemeContext.Provider>;
}

/**
 * HaloThemeProvider
 * Central orchestration for Light/Dark/System visual themes and
 * HaloUI physical material intensities (subtle, balanced, rich).
 */
export function HaloThemeProvider({
  children,
  defaultTheme = "system",
  defaultMaterialIntensity = "balanced",
  storageKey = "halo-theme",
  intensityStorageKey = "halo-material-intensity",
  attribute = "class",
  enableSystem = true,
  disableTransitionOnChange = false,
}: HaloThemeProviderProps) {
  return (
    <NextThemesProvider
      attribute={attribute}
      defaultTheme={defaultTheme}
      storageKey={storageKey}
      enableSystem={enableSystem}
      disableTransitionOnChange={disableTransitionOnChange}
    >
      <HaloThemeInnerProvider
        defaultMaterialIntensity={defaultMaterialIntensity}
        intensityStorageKey={intensityStorageKey}
      >
        {children}
      </HaloThemeInnerProvider>
    </NextThemesProvider>
  );
}

/**
 * useHaloTheme
 * Access current visual theme and material intensity state anywhere in the application.
 */
export function useHaloTheme(): HaloThemeContextValue {
  const context = React.useContext(HaloThemeContext);
  if (!context) {
    // Graceful fallback if rendered outside provider
    return {
      theme: "system",
      setTheme: () => {},
      resolvedTheme: "dark",
      materialIntensity: "balanced",
      setMaterialIntensity: () => {},
    };
  }
  return context;
}

/**
 * HaloUI Liquid Material Design System Tokens
 * Physical optical material engine: refraction, specular highlight, optical edges,
 * neoskeuomorphic depth, tactile compression, and virtual directional lighting.
 */

:root {
  /* Surface Tints (Light Mode: Luminous warm translucent body) */
  --halo-surface: rgba(255, 255, 255, 0.72);
  --halo-surface-elevated: rgba(255, 255, 255, 0.88);
  --halo-surface-strong: rgba(255, 255, 255, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.03);
  --halo-surface-tint: rgba(245, 245, 247, 0.45);

  /* Optical Edges (Light Mode: Fine micro-reflections) */
  --halo-edge: rgba(255, 255, 255, 0.9);
  --halo-edge-soft: rgba(0, 0, 0, 0.08);
  --halo-edge-bright: rgba(255, 255, 255, 1);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.9), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04);
  --halo-edge-outer: 0 0 0 1px rgba(0, 0, 0, 0.06);

  /* Specular Highlights (Directional: Virtual light at 135deg / top-left) */
  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.8) 0%, rgba(255, 255, 255, 0.15) 35%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.85;

  /* Optical Blur (Backdrop Diffusion) */
  --halo-blur-sm: 8px;
  --halo-blur-md: 16px;
  --halo-blur-lg: 28px;
  --halo-blur-xl: 44px;

  /* Shadows (Contact & Ambient anchoring) */
  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.08), 0 2px 4px 0 rgba(0, 0, 0, 0.04);
  --halo-shadow-elevated: 0 6px 16px -4px rgba(0, 0, 0, 0.08), 0 2px 6px -1px rgba(0, 0, 0, 0.04);
  --halo-shadow-ambient: 0 16px 36px -8px rgba(0, 0, 0, 0.1);
  --halo-shadow-compressed: 0 1px 1px 0 rgba(0, 0, 0, 0.1);

  /* Refraction Parameters */
  --halo-refraction-strength: 0.12;
  --halo-refraction-offset: 1.5px;
  --halo-noise-opacity: 0.025;
  --halo-glow: rgba(0, 0, 0, 0.04);

  /* Corner Radii */
  --halo-radius-sm: 8px;
  --halo-radius-md: 12px;
  --halo-radius-lg: 18px;
  --halo-radius-xl: 26px;
  --halo-radius-full: 9999px;

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #0284c7;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #ffffff;
  --halo-focus-outer-color: rgba(2, 132, 199, 0.25);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Motion Presets & Timing Architecture */
  --halo-duration-micro: 120ms;
  --halo-duration-state: 180ms;
  --halo-duration-reveal: 240ms;
  --halo-duration-settle: 320ms;
  --halo-ease-tactile: cubic-bezier(0.2, 0.8, 0.3, 1);
  --halo-ease-spring: cubic-bezier(0.16, 1, 0.3, 1);
  --halo-ease-out: cubic-bezier(0, 0, 0.2, 1);

  /* Typography & Canvas (Editorial warm tone) */
  --halo-canvas: #fbfbfd;
  --halo-canvas-card: #f5f5f7;
  --halo-canvas-subtle: #eaecee;
  --halo-text-primary: #121316;
  --halo-text-secondary: #585c65;
  --halo-text-tertiary: #8b909c;
}

.dark {
  /* Surface Tints (Dark Mode: Deep graphite optical body) */
  --halo-surface: rgba(22, 23, 26, 0.7);
  --halo-surface-elevated: rgba(30, 32, 38, 0.85);
  --halo-surface-strong: rgba(38, 41, 48, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.45);
  --halo-surface-tint: rgba(18, 19, 22, 0.6);

  /* Optical Edges (Dark Mode: Luminous rim catch & dark contact) */
  --halo-edge: rgba(255, 255, 255, 0.14);
  --halo-edge-soft: rgba(255, 255, 255, 0.06);
  --halo-edge-bright: rgba(255, 255, 255, 0.28);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.2), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.6);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);

  /* Specular Highlights (Directional top-left luminescence) */
  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0.04) 38%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;

  /* Shadows (Deep graphite depth) */
  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.4), 0 3px 6px 0 rgba(0, 0, 0, 0.3);
  --halo-shadow-elevated: 0 8px 24px -4px rgba(0, 0, 0, 0.65), 0 3px 8px -2px rgba(0, 0, 0, 0.4);
  --halo-shadow-ambient: 0 20px 48px -12px rgba(0, 0, 0, 0.85);
  --halo-shadow-compressed: 0 1px 2px 0 rgba(0, 0, 0, 0.6);

  --halo-refraction-strength: 0.18;
  --halo-noise-opacity: 0.035;
  --halo-glow: rgba(255, 255, 255, 0.04);

  /* Focus Ring Tokens (Shared Accessibility Infrastructure) */
  --halo-focus-color: #38bdf8;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color), 0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Typography & Canvas */
  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;
}

/* Material Intensity Presets */
.halo-intensity-subtle {
  --halo-active-blur: var(--halo-blur-sm);
  --halo-active-highlight: 0.4;
  --halo-active-edge: 0.7;
}

.halo-intensity-balanced {
  --halo-active-blur: var(--halo-blur-md);
  --halo-active-highlight: 0.85;
  --halo-active-edge: 1;
}

.halo-intensity-rich {
  --halo-active-blur: var(--halo-blur-lg);
  --halo-active-highlight: 1.2;
  --halo-active-edge: 1.35;
}

/* Tactile Physics Classes */
.halo-tactile-press {
  transition: transform 120ms cubic-bezier(0.2, 0.8, 0.3, 1),
              box-shadow 120ms cubic-bezier(0.2, 0.8, 0.3, 1),
              background-color 150ms ease;
}

.halo-tactile-press:active:not(:disabled) {
  transform: scale(0.98) translateY(1px);
  box-shadow: var(--halo-shadow-compressed), var(--halo-edge-inner), var(--halo-edge-outer) !important;
}

/* Focus Ring Accessibility Infrastructure */
.halo-focus-ring {
  outline: none;
}

.halo-focus-ring:focus-visible {
  outline: 2px solid var(--halo-focus-color) !important;
  outline-offset: var(--halo-focus-offset) !important;
  box-shadow: var(--halo-focus-shadow) !important;
  z-index: 10;
}

/* Forced Colors (High Contrast Mode) */
@media (forced-colors: active) {
  .halo-focus-ring:focus-visible {
    outline: 2px solid Highlight !important;
    outline-offset: 2px !important;
    box-shadow: none !important;
  }
}

/* Motion Presets Classes */
.halo-motion-press {
  transition: transform var(--halo-duration-micro) var(--halo-ease-tactile),
              box-shadow var(--halo-duration-micro) var(--halo-ease-tactile);
}

.halo-motion-press:active:not(:disabled) {
  transform: scale(0.98) translateY(1px);
}

.halo-motion-lift {
  transition: transform var(--halo-duration-state) var(--halo-ease-tactile),
              box-shadow var(--halo-duration-state) var(--halo-ease-tactile);
}

.halo-motion-lift:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: var(--halo-shadow-elevated);
}

.halo-motion-reveal {
  animation: halo-reveal var(--halo-duration-reveal) var(--halo-ease-spring) forwards;
}

.halo-motion-settle {
  transition: transform var(--halo-duration-settle) var(--halo-ease-spring),
              opacity var(--halo-duration-reveal) ease;
}

.halo-motion-float {
  animation: halo-float 3.5s ease-in-out infinite alternate;
}

@keyframes halo-reveal {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes halo-float {
  0% {
    transform: translateY(0px);
  }
  100% {
    transform: translateY(-6px);
  }
}

/* Reduced Motion Override */
@media (prefers-reduced-motion: reduce) {
  .halo-tactile-press,
  .halo-motion-press,
  .halo-motion-lift,
  .halo-motion-reveal,
  .halo-motion-settle,
  .halo-motion-float,
  .halo-motion-transition {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transform: none !important;
  }
}

/* ==========================================================================
   HALOUI MATERIAL INTENSITY ORCHESTRATION
   ========================================================================== */
[data-material-intensity="subtle"],
.halo-intensity-subtle {
  --halo-blur-strength: 8px;
  --halo-highlight-multiplier: 0.40;
  --halo-glow-spread: 12px;
}

[data-material-intensity="balanced"],
.halo-intensity-balanced {
  --halo-blur-strength: 16px;
  --halo-highlight-multiplier: 0.85;
  --halo-glow-spread: 24px;
}

[data-material-intensity="rich"],
.halo-intensity-rich {
  --halo-blur-strength: 28px;
  --halo-highlight-multiplier: 1.20;
  --halo-glow-spread: 36px;
}
